contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We test that calling setSlopes with a kink in (0, 1e27) does not revert.
    // We observe this by attempting the call inside try/catch and then calling rate (a public function)
    // to ensure the contract remains callable. The assert requires that setSlopes with valid kink
    // does not revert, i.e., reverted == false.

    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1, address vault, address dummyVaultAsset) public payable {
        require(asset != address(0));
        // constrain kink to the range the rule is about; the test will only assert behavior for such kinks
        require(kink > 0 && kink < 1e27);

        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1});

        bool reverted;
        try c.setSlopes(asset, slopes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After attempting setSlopes, ensure the contract still answers to a rate() call (may revert if setSlopes reverted,
        // but we only require that setSlopes with valid kink does not revert).
        bool rateReverted;
        try c.rate(vault, dummyVaultAsset) returns (uint256) {
            rateReverted = false;
        } catch {
            rateReverted = true;
        }

        // General rule: for a kink in (0,1e27), setSlopes must not revert.
        // We assert that reverted == false. This is a non-trivial property about state-changing call acceptance.
        assert(reverted == false);
    }

    receive() external payable {}
}

