contract InvMutTest {
    C c;

    event SetSlopes(address indexed _asset, IVaultAdapter.SlopeData _slopes);

    constructor(C _c) { c = _c; }

    // We take an _asset, slopes fields and an _accessControl address used only for initialization in fresh deployments.
    // The test tries to call setSlopes and records whether it reverted. It then asserts the general rule:
    // - If _slopes.kink == 0 or >= 1e27 then the call must revert (InvalidKink).
    // - Otherwise the call must succeed and emit the SetSlopes event with the same asset and slopes.
    function run(address _asset, uint256 kink, uint256 slope0, uint256 slope1, address _accessControl) public payable {
        require(_asset != address(0));
        // Prepare the slopes struct in calldata encoding
        bytes memory data = abi.encode(IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1}));

        bool reverted;
        // Listen for event by using try/catch around the external call; also attempt to capture logs is not possible here,
        // so instead we rely on the fact that a successful call does not revert. We also read back storage indirectly
        // by calling setSlopes only and trusting its emission as the observable effect. Since emitted events cannot
        // be read here, we re-check by attempting a second call: calling setSlopes again with the same valid params
        // should not revert and is idempotent in terms of acceptance (will succeed). For invalid kinks the first call should revert.

        // First, attempt the call and record revert status.
        try c.setSlopes(_asset, abi.decode(data, (IVaultAdapter.SlopeData))) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Now assert the general rule: invalid kink <=> reverted, valid kink => not reverted
        // invalid when kink == 0 or kink >= 1e27
        bool invalidKink = (kink == 0 || kink >= 1e27);

        // Exactly one assert as required
        assert((invalidKink && reverted) || (!invalidKink && !reverted));
    }

    // allow receiving Ether if needed by future variants
    receive() external payable {}
}

