contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will test setSlopes behavior: invalid kink should revert, valid kink should not revert
    // and should allow subsequent rate(...) to execute (not revert) when called with some vault/asset.
    // We cannot observe events directly, so we assert on revert flags and that rate call does not revert
    // for the valid kink case.
    function run(address vault, address asset, uint256 kink, uint256 slope0, uint256 slope1) public payable {
        require(vault != address(0) && asset != address(0));

        IVaultAdapter.SlopeData memory slopes = IVaultAdapter.SlopeData({
            kink: kink,
            slope0: slope0,
            slope1: slope1
        });

        bool setReverted;
        try c.setSlopes(asset, slopes) {
            setReverted = false;
        } catch {
            setReverted = true;
        }

        // Try calling rate afterwards and record whether it reverts
        bool rateReverted;
        try c.rate(vault, asset) returns (uint256 r) {
            rateReverted = false;
        } catch {
            rateReverted = true;
        }

        // General rule asserted here:
        // If kink is invalid (kink == 0 or kink >= 1e27) then setSlopes must revert.
        // If kink is valid (0 < kink < 1e27) then setSlopes must not revert, and a subsequent call to rate(vault,asset)
        // must NOT revert (rate may still revert for other reasons in pathological envs, but in the contract design
        // a successful setSlopes with valid kink should not cause rate to revert solely due to slope storage).
        assert(
            ((kink == 0 || kink >= 1e27) && setReverted && (rateReverted || true))
            || ((kink > 0 && kink < 1e27) && !setReverted && !rateReverted)
        );
    }

