    constructor(C _c) { c = _c; }

    // We will test that calling setSlopes with a kink in (0,1e27) does not revert and
    // allows later calls depending on slopes to proceed; if setSlopes is called with
    // invalid kink (==0 or >=1e27) it must revert; we capture that. We cannot read
    // private storage directly, so we assert a relation between revert flags and
    // ability to call rate (which uses slopeData internally).
    function run(address vault, address asset, uint256 kink, uint256 slope0, uint256 slope1, uint256 dummyAmount) public payable {
        require(vault != address(0) && asset != address(0));
        // Prepare slopes struct bytes for calldata. Use same layout as SlopeData(uint256,uint256,uint256)
        bytes memory slopesData = abi.encode(kink, slope0, slope1);

        bool setReverted;
        // Call setSlopes and catch revert
        try c.setSlopes(asset, abi.decode(slopesData, (C.SlopeData))) {
            setReverted = false;
        } catch {
            setReverted = true;
        }

        // Now attempt to call rate. rate may revert for many reasons; we only observe whether it reverts.
        bool rateReverted;
        try c.rate(vault, asset) returns (uint256 r) {
            rateReverted = false;
        } catch {
            rateReverted = true;
        }

        // General rule asserted:
        // If setSlopes did not revert then kink must have been in the valid range (0,1e27)
        // and rate should not revert solely due to InvalidKink from slopes storage; conversely,
        // if kink is invalid then setSlopes must revert (we cannot guarantee rate behavior then).
        // We express this as: (set succeeded) => (0 < kink && kink < 1e27) && (!set succeeded || rate may be anything)
        // The assert must be a non-trivial relation: we assert that setSlopes succeeds iff kink in (0,1e27).

        assert((!setReverted) == (kink > 0 && kink < 1e27));
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We test that setSlopes reverts iff kink == 0 or kink >= 1e27.
    // Because SlopeData type is not accessible here as C.SlopeData, we pass the struct fields
    // by encoding/decoding to bytes and using low-level call to invoke setSlopes.
    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1) public payable {
        require(asset != address(0));

        // Prepare calldata for setSlopes(address, (uint256,uint256,uint256))
        // function selector for setSlopes(address,(uint256,uint256,uint256))
        bytes4 sig = bytes4(keccak256("setSlopes(address,(uint256,uint256,uint256))"));
        bytes memory inner = abi.encode(kink, slope0, slope1);
        bytes memory data = abi.encodePacked(sig, abi.encode(asset, inner));

        bool setReverted;
        // low-level call to capture revert without needing the SlopeData type
        (bool ok, ) = address(c).call(data);
        setReverted = !ok;

        // The property: setSlopes should revert iff kink == 0 || kink >= 1e27
        assert(setReverted == (kink == 0 || kink >= 1e27));
    }

    receive() external payable { }
}

