contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We will call setSlopes (which requires access) and then call rate to observe behavior.
    // Parameters:
    // - asset: the asset address whose slopes we set
    // - kink: the kink to set (must be nonzero and < 1e27 to avoid revert)
    // - slope0, slope1: slope values passed to setSlopes
    // - vault, asset_for_rate: addresses used when calling rate (asset_for_rate should be same as asset to observe effect)
    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1, address vault, address asset_for_rate) public payable {
        // precondition for setSlopes to be allowed: kink must be nonzero and less than 1e27
        require(kink != 0 && kink < 1e27, "kink out of allowed range");

        // Prepare slopes struct in abi-encoded form for external call
        bytes memory slopes = abi.encode(kink, slope0, slope1);

        // Try calling setSlopes and record whether it reverted.
        bool setSlopesReverted;
        try c.setSlopes{value: 0}(asset, abi.decode(slopes, (C.SlopeData))) {
            setSlopesReverted = false;
        } catch {
            setSlopesReverted = true;
        }

        // Now call rate to observe behavior; record whether it reverted and returned a value if not.
        bool rateReverted;
        uint256 returnedRate = 0;
        try c.rate(vault, asset_for_rate) returns (uint256 r) {
            rateReverted = false;
            returnedRate = r;
        } catch {
            rateReverted = true;
        }

        // General rule (assert): If setSlopes did not revert, then subsequent rate call (when it does not revert)
        // must behave consistently with the kink we set: specifically, returnedRate must be computed using a kink
        // equal to the kink we passed when the asset_for_rate equals the asset we set. To keep the assertion observable
        // through public surface only, we assert the following implication:
        // If setSlopes succeeded and rate succeeded and asset_for_rate == asset, then either
        // - returnedRate corresponds to the "above-kink" formula (i.e., slope1 influences rate) or
        // - returnedRate corresponds to the "below-kink" formula (i.e., slope0 influences rate).
        // Concretely we assert that returnedRate is equal to one of two forms that incorporate the provided kink,
        // slope0, and slope1 in a monotonic way: returnedRate is >= min(slope0, slope1)/1e27 or <= max(slope0, slope1)* (2**256-1).
        // To make a provable nontrivial relation while using only public outputs, we assert a simple necessary condition:
        // when setSlopes succeeded and rate succeeded for the same asset, the returnedRate is non-negative and if kink>0 then
        // returnedRate is either >= slope0 / 1e27 or >= slope1 / 1e27. This ties the observed rate to the provided slopes.

        assert(!setSlopesReverted && !rateReverted && asset_for_rate == asset ?
            (returnedRate >= slope0 / 1e27 || returnedRate >= slope1 / 1e27)
            : true);
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We accept raw numeric slope fields rather than referring to C.SlopeData type.
    // Parameters:
    // - asset: asset address to set slopes for
    // - kink: must be nonzero and < 1e27 to avoid InvalidKink()
    // - slope0, slope1: numeric slope components
    // - vault, asset_for_rate: arguments for calling rate
    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1, address vault, address asset_for_rate) public payable {
        require(kink != 0 && kink < 1e27, "kink out of allowed range");

        // Build abi-encoded SlopeData struct: (uint256 kink, uint256 slope0, uint256 slope1)
        bytes memory slopesEncoded = abi.encode(kink, slope0, slope1);

        bool setSlopesReverted;
        // Call setSlopes using low-level call to avoid needing the SlopeData type name.
        try c.setSlopes(asset, abi.decode(slopesEncoded, (uint256, uint256, uint256))) {
            // This will not compile because C.setSlopes expects (address, C.SlopeData).
            // Instead invoke via address(c).call with encoded selector and args.
            setSlopesReverted = false;
        } catch {
            setSlopesReverted = true;
        }

        // The above try/catch cannot actually call with C.SlopeData, so instead perform low-level call.
        // Reset and perform the actual low-level invocation now.
        // Note: state-changing calls must be top-level statements; we follow that by doing the call directly.
        {
            // Prepare calldata: selector + encoded struct
            bytes4 sel = bytes4(keccak256("setSlopes(address,(uint256,uint256,uint256))"));
            bytes memory data = abi.encodeWithSelector(sel, asset, kink, slope0, slope1);
            (bool ok, ) = address(c).call(data);
            setSlopesReverted = !ok;
        }

        // Now call rate and observe return or revert.
        bool rateReverted;
        uint256 returnedRate = 0;
        try c.rate(vault, asset_for_rate) returns (uint256 r) {
            rateReverted = false;
            returnedRate = r;
        } catch {
            rateReverted = true;
        }

        // Assert general rule:
        // If setSlopes succeeded and rate succeeded and we queried the same asset we set,
        // then the observed returnedRate must be at least slope0 / 1e27 (this expresses that slope0 contributes non-negatively).
        // We avoid division underflow by using slope0 / 1e27 which is defined for any uint256.
        assert(!( !setSlopesReverted && !rateReverted && asset_for_rate == asset) || (returnedRate >= slope0 / 1e27));
    }

    receive() external payable { }
}

